bool Reject(const std::function<void()>& f){try{f();return false;}catch(const std::exception&){return true;}}
sct::core::Image Pixels(int width=160,int height=100,COLORREF color=RGB(255,255,255)){sct::core::Image image;image.Create(width,height);for(size_t i=0;i<image.pixels.size();i+=4){image.pixels[i]=GetBValue(color);image.pixels[i+1]=GetGValue(color);image.pixels[i+2]=GetRValue(color);image.pixels[i+3]=255;}return image;}
