uint32_t Crc(const std::vector<BYTE>& data){uint32_t crc=~0u;for(BYTE c:data){crc^=c;for(int i=0;i<8;++i)crc=(crc>>1)^(0xEDB88320u&uint32_t(-int(crc&1)));}return ~crc;}
